1	"use server";
2	
3	// Server actions behind the billing page's card LIST — add/remove/make-primary
4	// against the `PaymentCard` table (lib/stripe-cards.ts owns the mechanics; this
5	// file is just the "use server" surface, the same split actions-payment-method.ts
6	// uses). Adding a card still goes through `startCardSetup`/`finalizeCardSetup`
7	// in that file UNCHANGED — `persistCard` underneath was made multi-card-aware,
8	// so nothing about the Stripe redirect/embedded-checkout flow needed to change
9	// to support a second, third, fourth card.
10	
11	import { revalidatePath } from "next/cache";
12	import { requireUser, assertNotImpersonating } from "./auth";
13	import { removePaymentCard, setPrimaryPaymentCard } from "./stripe-cards";
14	
15	export async function removeCardById(cardId: string): Promise<{ ok?: boolean; error?: string }> {
16	  await assertNotImpersonating();
17	  const user = await requireUser();
18	  const res = await removePaymentCard(user.id, cardId);
19	  if (res.error) return { error: res.error };
20	  revalidatePath("/dashboard/billing");
21	  return { ok: true };
22	}
23	
24	export async function makeCardPrimary(cardId: string): Promise<{ ok?: boolean; error?: string }> {
25	  await assertNotImpersonating();
26	  const user = await requireUser();
27	  const res = await setPrimaryPaymentCard(user.id, cardId);
28	  if (res.error) return { error: res.error };
29	  revalidatePath("/dashboard/billing");
30	  return { ok: true };
31	}
