1	"use server";
2	
3	/**
4	 * Setting and clearing the card image a customer chooses for one of their own
5	 * services on /dashboard/services.
6	 *
7	 * Every action authenticates the caller and verifies they OWN the target
8	 * server (admins may act on any), the same `ownedServer` shape the rest of the
9	 * server-scoped actions use, and rate-limits per user. The bytes are validated
10	 * by lib/chat-attachment's magic-number sniffer rather than the client-declared
11	 * type, so an SVG (which can carry script) or a renamed file is rejected on the
12	 * real signature — the identical core the live-chat upload path is reviewed on.
13	 */
14	import { db } from "./db";
15	import { requireUser } from "./auth";
16	import { checkRateLimit } from "./rate-limit";
17	import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "./chat-attachment";
18	import { revalidatePath } from "next/cache";
19	
20	type Result = { ok: true } | { ok: false; error: string };
21	
22	/** The server, only if this caller may act on it. */
23	async function ownedServer(userId: string, role: string, serverId: string) {
24	  return db.server.findFirst({
25	    where: role === "ADMIN" ? { id: serverId } : { id: serverId, userId },
26	    select: { id: true, gamePlanId: true },
27	  });
28	}
29	
30	export async function setServicePreview(serverId: string, form: FormData): Promise<Result> {
31	  const user = await requireUser();
32	
33	  const rl = checkRateLimit(`service-preview:${user.id}`, { max: 12, windowMs: 60_000 });
34	  if (!rl.ok) return { ok: false, error: "Too many uploads. Please slow down." };
35	
36	  const server = await ownedServer(user.id, user.role, serverId);
37	  if (!server) return { ok: false, error: "Service not found." };
38	  // Game servers lead with their game's own key art; there is nothing for a
39	  // custom image to improve on there, and the card never offers the control.
40	  if (server.gamePlanId !== null) {
41	    return { ok: false, error: "Game servers use their game's artwork." };
42	  }
43	
44	  const file = form.get("file");
45	  if (!(file instanceof File)) return { ok: false, error: "No image provided." };
46	  // Cheap guard before buffering the whole body into memory.
47	  if (file.size > MAX_ATTACHMENT_BYTES) return { ok: false, error: "Image is larger than 5 MB." };
48	
49	  const check = validateImageBytes(Buffer.from(await file.arrayBuffer()), file.type);
50	  if (!check.ok) return { ok: false, error: check.error };
51	
52	  // Prisma's Bytes field wants a plain Uint8Array over a definite ArrayBuffer,
53	  // which a Node Buffer's `ArrayBufferLike` doesn't satisfy on its own.
54	  const bytes = new Uint8Array(check.bytes);
55	
56	  await db.servicePreview.upsert({
57	    where: { serverId: server.id },
58	    create: { serverId: server.id, mime: check.mime, bytes },
59	    update: { mime: check.mime, bytes },
60	  });
61	
62	  revalidatePath("/dashboard/services");
63	  return { ok: true };
64	}
65	
66	export async function clearServicePreview(serverId: string): Promise<Result> {
67	  const user = await requireUser();
68	  const server = await ownedServer(user.id, user.role, serverId);
69	  if (!server) return { ok: false, error: "Service not found." };
70	
71	  await db.servicePreview.deleteMany({ where: { serverId: server.id } });
72	  revalidatePath("/dashboard/services");
73	  return { ok: true };
74	}
