190	    // CardSetupModal's `<PaymentElement>`, styled with the shared
191	    // STRIPE_APPEARANCE/STRIPE_FONTS rather than Stripe's default light
192	    // theme. This used to be `EMBEDDED_UI_MODE` ("embedded_page", Stripe's
193	    // own prebuilt page) — the one Stripe surface on the whole platform that
194	    // never got migrated when everything else did, which is exactly why
195	    // "Add a card" looked like an unstyled Stripe form. On completion Stripe
196	    // navigates to `return_url` (returnPath?card_setup=<id>) where the
197	    // existing finalize-on-return logic runs UNCHANGED — this is a pure
198	    // presentation change, same Checkout Session shape either way.
199	    ui_mode: CUSTOM_CHECKOUT_UI_MODE,
200	    customer: customerId,
201	    payment_method_types: ["card"],
202	    setup_intent_data: { metadata: { nxeonUserId: user.id } },
203	    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
204	    // returnPath may already carry a query (e.g. the Deploy hub's ?product=hosting),
205	    // so append card_setup with the correct separator.
206	    return_url: `${base}${returnPath}${returnPath.includes("?") ? "&" : "?"}card_setup={CHECKOUT_SESSION_ID}`,
207	  }, EMBEDDED_REQUEST_OPTS);
208	  return session.client_secret ? { clientSecret: session.client_secret, publishableKey: stripePublishableKey() } : null;
209	}
210	
211	/**
212	 * Copy the PRIMARY PaymentCard row's fields onto `User`'s mirror columns — the
213	 * one place that keeps the two in sync. Every renewal/dunning/off-session
214	 * charge path reads ONLY the `User` columns (`stripePaymentMethodId`,
215	 * `cardBrand`, etc.), never the `PaymentCard` table directly, so those paths
216	 * are completely unaffected by a customer having two cards or six: whichever
217	 * one is primary is always what they see. No primary left (the list is
218	 * empty) clears the mirror, the same as `clearCardColumns` always did.
219	 */
220	async function mirrorPrimaryCardToUser(userId: string, customerId?: string) {
221	  const primary = await db.paymentCard.findFirst({ where: { userId, isPrimary: true } });
222	  if (!primary) {
223	    await clearCardColumns(userId);
224	    return;
225	  }
226	  await db.user.update({
227	    where: { id: userId },
228	    data: {
229	      ...(customerId ? { stripeCustomerId: customerId } : {}),
230	      stripePaymentMethodId: primary.stripePaymentMethodId,
231	      cardBrand: primary.brand,
232	      cardLast4: primary.last4,
233	      cardExpMonth: primary.expMonth,
234	      cardExpYear: primary.expYear,
235	      cardExpiryNotifiedAt: null,
236	    },
237	  });
238	}
239	
240	/**
241	 * Add or refresh one card in the customer's list, then re-mirror the primary
242	 * onto `User`. A card that already exists (same Stripe payment method id —
243	 * e.g. Checkout re-attaching the same card after a browser refresh) is
244	 * updated in place, never duplicated. A BRAND NEW card becomes primary only
245	 * when the customer has no primary yet — adding a second card must never
246	 * silently switch what a pending renewal is about to charge.
247	 */
248	async function persistCard(userId: string, customerId: string, pm: Stripe.PaymentMethod) {
249	  const existing = await db.paymentCard.findUnique({ where: { stripePaymentMethodId: pm.id } });
250	  const hasPrimary = existing?.isPrimary || (await db.paymentCard.count({ where: { userId, isPrimary: true } })) > 0;
251	  await db.paymentCard.upsert({
252	    where: { stripePaymentMethodId: pm.id },
253	    create: {
254	      userId,
255	      stripePaymentMethodId: pm.id,
256	      brand: pm.card?.brand ?? null,
257	      last4: pm.card?.last4 ?? null,
258	      expMonth: pm.card?.exp_month ?? null,
259	      expYear: pm.card?.exp_year ?? null,
260	      isPrimary: !hasPrimary,
261	    },
262	    update: {
263	      brand: pm.card?.brand ?? null,
264	      last4: pm.card?.last4 ?? null,
265	      expMonth: pm.card?.exp_month ?? null,
266	      expYear: pm.card?.exp_year ?? null,
267	    },
268	  });
269	  await mirrorPrimaryCardToUser(userId, customerId);
270	}
271	
272	export type SavedCard = { brand: string | null; last4: string | null; expMonth: number | null; expYear: number | null };
273	
274	export type PaymentCardView = {
275	  id: string; brand: string | null; last4: string | null;
276	  expMonth: number | null; expYear: number | null; isPrimary: boolean;
277	};
278	
279	/** Every card a customer has saved, primary first — for the billing page's list. */
280	export async function listPaymentCards(userId: string): Promise<PaymentCardView[]> {
281	  const rows = await db.paymentCard.findMany({
282	    where: { userId },
283	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
284	  });
285	  return rows.map((r) => ({
286	    id: r.id, brand: r.brand, last4: r.last4, expMonth: r.expMonth, expYear: r.expYear, isPrimary: r.isPrimary,
287	  }));
288	}
289	
290	/**
291	 * Make one of the customer's own cards primary and re-mirror it onto `User` —
292	 * the effect being that the NEXT renewal/off-session charge uses this card.
293	 * The whole flip is one transaction so a concurrent add/remove can never leave
294	 * two cards (or zero) marked primary.
295	 */
296	export async function setPrimaryPaymentCard(userId: string, cardId: string): Promise<{ ok?: true; error?: string }> {
297	  const card = await db.paymentCard.findUnique({ where: { id: cardId } });
298	  if (!card || card.userId !== userId) return { error: "Card not found." };
299	  if (!card.isPrimary) {
300	    await db.$transaction([
301	      db.paymentCard.updateMany({ where: { userId, isPrimary: true }, data: { isPrimary: false } }),
302	      db.paymentCard.update({ where: { id: cardId }, data: { isPrimary: true } }),
303	    ]);
304	    await mirrorPrimaryCardToUser(userId);
305	  }
306	  return { ok: true };
307	}
308	
309	/**
310	 * Remove ONE saved card by id (detach at Stripe first, same ordering
311	 * `detachSavedCard` uses and for the same reason — a method still attached at
312	 * Stripe when our row disappears is a method `adoptUnclaimedCards` could
313	 * re-adopt). Removing the primary card promotes the next-oldest remaining one
314	 * automatically, so a customer with two cards never ends up with neither
315	 * mirrored onto `User` by accident; removing the last card clears the mirror
316	 * exactly the way it always has.
317	 */
