 *  authorises sending one — anyone who may invite may un-invite. The token is
 *  not revoked (it cannot be, it is stateless and already sent); `acceptInvite`
 *  checks this row and refuses, which is what makes the button mean something. */
export async function revokeInvite(orgId: string, email: string): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  /* Same two-step the invite path uses: resolve the caller's membership in THIS
     org, then ask whether that role may administer it. `canAdministerOrg` takes
     a role, not a user — it is the single definition of the permission and both
     paths go through it. */
  const actor = await actorMembership(orgId, user.id);
  if (!actor || !canAdministerOrg(actor.role)) {
    return { error: "You don't have permission to manage invitations for this organization." };
  }
  const r = await db.orgInvite.updateMany({
    where: { orgId, email: email.trim().toLowerCase(), acceptedAt: null, revokedAt: null },
    data: { revokedAt: new Date() },
  });
  if (r.count === 0) return { error: "That invitation has already been accepted or cancelled." };
  revalidatePath("/dashboard/team");
  return { ok: true };
}

