83	    select: {
84	      id: true, userId: true, status: true, username: true, primaryDomain: true,
85	      diskQuotaMB: true, extraDiskGB: true, expiresAt: true, planId: true,
86	      plan: { select: { diskGB: true, name: true } },
87	    },
88	  });
89	  if (!a) return { error: "Account not found." };
90	  if (a.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
91	  if (opts.active && a.status !== "ACTIVE") return { error: "The account is still being set up." };
