144	/** Every stored picture on an account, keyed by site. Owner or admin. */
145	export async function listSiteThumbs(accountId: string): Promise<SiteThumbView[]> {
146	  const ctx = await ownedAccount(accountId);
147	  if ("error" in ctx) return [];
148	  const rows = await db.hostingSiteThumb.findMany({
149	    where: { accountId },
150	    select: {
151	      id: true, siteKey: true, hostname: true, source: true, status: true,
152	      error: true, capturedAt: true, updatedAt: true, sizeBytes: true,
153	    },
154	  });
155	  // Resolve each key's CURRENT hostname so a stale picture can be flagged rather
156	  // than shown as though it depicts the site as it is now.
157	  const current = new Map<string, string>();
158	  const [subs, addons] = await Promise.all([
159	    db.hostingSubdomain.findMany({ where: { accountId }, select: { id: true, fqdn: true } }),
160	    db.hostingAddonDomain.findMany({ where: { accountId }, select: { id: true, domain: true } }),
161	  ]);
162	  current.set("primary", ctx.a.primaryDomain);
163	  for (const s of subs) current.set(`subdomain:${s.id}`, s.fqdn);
164	  for (const d of addons) current.set(`addon:${d.id}`, d.domain);
165	
166	  return rows.map((r) => ({
167	    siteKey: r.siteKey,
168	    hostname: r.hostname,
169	    source: r.source as "CAPTURE" | "UPLOAD",
170	    status: r.status as "PENDING" | "READY" | "FAILED",
171	    stale: (current.get(r.siteKey) ?? r.hostname) !== r.hostname,
172	    error: r.error,
173	    capturedAt: r.capturedAt?.toISOString() ?? null,
174	    // Cache-bust on updatedAt so a re-capture replaces the picture immediately.
175	    url: r.status === "READY" && r.sizeBytes > 0
176	      ? `/api/hosting/thumb?id=${r.id}&v=${r.updatedAt.getTime()}`
177	      : null,
178	  }));
179	}
