360	/** Reveal a scoped login's password. Owner only; never while impersonating —
361	 *  same rule as the account's own SFTP credential. */
362	export async function revealFtpPassword(id: string): Promise<{ password?: string; error?: string }> {
363	  const user = await requireUser();
364	  await assertNotImpersonating();
365	  const row = await db.hostingFtpUser.findUnique({
366	    where: { id },
367	    select: { passwordEnc: true, account: { select: { userId: true } } },
368	  });
369	  if (!row) return { error: "Not found." };
370	  if (row.account.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
371	  const pw = decryptSecret(row.passwordEnc);
372	  if (!pw) return { error: "No password on record — reset it to set a new one." };
373	  return { password: pw };
