449	/* ══ storage add-on ═══════════════════════════════════════════════════════ */
450	
451	export type StorageQuote = {
452	  planDiskGB: number;
453	  extraDiskGB: number;
454	  effectiveGB: number;
455	  /** Largest single purchase still allowed under the effective-disk ceiling. */
456	  maxAddGB: number;
457	  stepGB: number;
458	  minGB: number;
459	  perGbCents: number;
460	  /** Whole months left on the paid term — what the one-off charge prorates over. */
461	  monthsRemaining: number;
462	  /** For the amount asked about: the monthly add and the charge due now. */
463	  addGB: number;
464	  monthlyCents: number;
465	  chargeNowCents: number;
466	  walletCents: number;
467	};
468	
469	/**
470	 * Price extra storage for a hosting account, using the SAME helpers the VPS
471	 * add-storage path uses (lib/extra-disk.ts + lib/proration.ts) so the figure a
472	 * customer is shown is the figure the charge is computed from. Nothing here
473	 * spends anything.
474	 */
475	export async function quoteHostingStorage(accountId: string, addGBRaw: number): Promise<StorageQuote | Fail> {
476	  const ctx = await ownedAccount(accountId);
477	  if ("error" in ctx) return { error: ctx.error };
478	  const planDiskGB = ctx.a.plan.diskGB;
479	  const extra = ctx.a.extraDiskGB ?? 0;
480	  const perGbCents = await extraDiskPerGbCents();
481	  const months = remainingMonths(ctx.a.expiresAt, Date.now());
482	  const addGB = normalizeExtraDiskGB(addGBRaw);
483	  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
484	  return {
485	    planDiskGB,
486	    extraDiskGB: extra,
487	    effectiveGB: effectiveDiskGB(planDiskGB, extra),
488	    maxAddGB: maxAddableExtraDiskGB(planDiskGB, extra),
489	    stepGB: EXTRA_DISK_STEP_GB,
490	    minGB: EXTRA_DISK_MIN_GB,
491	    perGbCents,
492	    monthsRemaining: months,
493	    addGB,
494	    monthlyCents,
495	    chargeNowCents: extraDiskProrateCents(monthlyCents, months),
496	    walletCents: ctx.user.balanceCents,
497	  };
498	}
499	
500	/**
501	 * Buy extra storage for a hosting account, post-deploy.
502	 *
503	 * Until now extra storage could only be bought AT ORDER TIME (the deploy
504	 * wizard's slider); a customer who filled up had nothing to click. This is the
505	 * same shape as upgradeHostingPlan: one wallet debit, in the same transaction
506	 * that raises the quota, then an APPLY_PLAN_LIMITS task so the node's `setquota`
507	 * actually grows. No card fallback — a customer without the balance is told to
508	 * top up, rather than being taken through a second payment surface this action
509	 * cannot supervise.
510	 *
511	 * GROWTH IS ONE-WAY, exactly like the VPS path: a live filesystem quota is only
512	 * ever raised. The control says so before the money moves.
513	 */
514	export async function expandHostingStorage(accountId: string, addGBRaw: number): Promise<SiteResult> {
515	  const ctx = await ownedAccount(accountId, { active: true });
516	  if ("error" in ctx) return { error: ctx.error };
517	  await assertNotImpersonating();
518	
519	  const addGB = normalizeExtraDiskGB(addGBRaw);
520	  if (!isValidExtraDiskAddGB(addGB)) {
521	    return { error: `Storage is sold in ${EXTRA_DISK_STEP_GB} GB steps, from ${EXTRA_DISK_MIN_GB} GB.` };
522	  }
523	  const planDiskGB = ctx.a.plan.diskGB;
524	  const extra = ctx.a.extraDiskGB ?? 0;
525	  const maxAdd = maxAddableExtraDiskGB(planDiskGB, extra);
526	  if (addGB > maxAdd) {
527	    return maxAdd === 0
528	      ? { error: "This account is already at the maximum storage we can attach. Contact support about a larger plan." }
529	      : { error: `You can add at most ${maxAdd} GB to this account in one go.` };
530	  }
531	
532	  const perGbCents = await extraDiskPerGbCents();
533	  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
534	  const chargeCents = extraDiskProrateCents(monthlyCents, remainingMonths(ctx.a.expiresAt, Date.now()));
535	  if (ctx.user.balanceCents < chargeCents) {
536	    return { error: "Insufficient balance. Top up your wallet first." };
537	  }
538	
539	  const newExtra = extra + addGB;
540	  // diskQuotaMB is the account's effective quota and ALWAYS already includes the
541	  // add-on (see the schema note), so both move together or neither does.
542	  const newQuotaMB = effectiveDiskGB(planDiskGB, newExtra) * 1024;
543	
544	  try {
545	    await db.$transaction(async (tx) => {
546	      if (chargeCents > 0) {
547	        await debitWallet(tx, ctx.user.id, chargeCents);
548	        await tx.walletTransaction.create({
549	          data: {
550	            userId: ctx.user.id,
551	            amountCents: -chargeCents,
552	            description: `Web Hosting extra storage: +${addGB} GB for ${ctx.a.primaryDomain}`,
553	          },
554	        });
555	      }
556	      await tx.hostingAccount.update({
557	        where: { id: ctx.a.id },
558	        data: { extraDiskGB: newExtra, diskQuotaMB: newQuotaMB },
559	      });
560	      await tx.hostingTask.create({ data: { accountId: ctx.a.id, kind: "APPLY_PLAN_LIMITS" } });
561	    });
562	  } catch (e) {
563	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
564	    return { error: "Couldn’t add the storage. Your wallet was not charged — try again." };
565	  }
566	
567	  await db.auditLog.create({
568	    data: { userId: ctx.user.id, action: "hosting.storage.add", detail: `+${addGB} GB · ${ctx.a.primaryDomain}` },
569	  }).catch(() => {});
570	  revalidatePath(`/dashboard/hosting/${accountId}`);
571	  return { ok: true };
572	}
