574	/* ══ storage breakdown ════════════════════════════════════════════════════ */
575	
576	export type StorageBreakdown = {
577	  /** Measured total, MB. Null when no sweep has run against a real node. */
578	  usedMB: number | null;
579	  quotaMB: number;
580	  inodes: number | null;
581	  measuredAt: string | null;
582	  /** One entry per measured directory. Empty when unmeasured — never invented. */
583	  parts: { path: string; label: string; mb: number }[];
584	  /** Backups live on the node OUTSIDE the account's quota, so they are reported
585	   *  separately rather than folded into the bar. */
586	  backupCount: number;
587	  backupBytes: number;
588	  /** Why there is nothing to show, when there is nothing to show. */
589	  note: string | null;
590	};
591	
592	const DIR_LABELS: Record<string, string> = {
593	  public_html: "Main website",
594	  subdomains: "Subdomains",
595	  domains: "Addon domains",
596	  tmp: "Temporary files",
597	  logs: "Logs",
598	  ".cache": "Caches",
599	};
600	
601	function labelForDir(path: string): string {
602	  if (DIR_LABELS[path]) return DIR_LABELS[path];
603	  const sub = /^subdomains\/([^/]+)/.exec(path);
604	  if (sub) return sub[1];
605	  const dom = /^domains\/([^/]+)/.exec(path);
606	  if (dom) return dom[1];
607	  return path;
608	}
609	
610	/**
611	 * Where an account's storage is actually going.
612	 *
613	 * `usageBreakdown` is written by hostingUsageSweep in the same pass that writes
614	 * `diskUsedMB`, one `du -sm` per directory, so the parts and the total are
615	 * measured together. When it is null there has been no sweep — this returns an
616	 * empty `parts` and a `note` saying why, and the card renders the reason instead
617	 * of a chart of zeroes.
618	 */
619	export async function hostingStorageBreakdown(accountId: string): Promise<StorageBreakdown | Fail> {
620	  const ctx = await ownedAccount(accountId);
621	  if ("error" in ctx) return { error: ctx.error };
622	  const a = await db.hostingAccount.findUnique({
623	    where: { id: accountId },
624	    select: { diskUsedMB: true, diskQuotaMB: true, inodesUsed: true, usageAt: true, usageBreakdown: true, status: true },
625	  });
626	  if (!a) return { error: "Account not found." };
627	
628	  const backups = await db.hostingBackup.findMany({ where: { accountId }, select: { sizeBytes: true } });
629	
630	  let parts: { path: string; label: string; mb: number }[] = [];
631	  let note: string | null = null;
632	  if (a.usageBreakdown) {
633	    try {
634	      const parsed = JSON.parse(a.usageBreakdown) as { dirs?: { path: string; mb: number }[] };
635	      parts = (parsed.dirs ?? [])
636	        .filter((d) => typeof d?.path === "string" && Number.isFinite(d?.mb))
637	        .map((d) => ({ path: d.path, label: labelForDir(d.path), mb: Math.max(0, Math.round(d.mb)) }))
638	        .sort((x, y) => y.mb - x.mb);
639	    } catch {
640	      note = "The last usage reading couldn’t be read back.";
641	    }
642	  } else {
643	    note = SANDBOX
644	      ? "No hosting node is attached in this environment, so nothing has been measured."
645	      : a.status === "ACTIVE"
646	        ? "We haven’t measured this account yet — the first reading lands within a few minutes of going live."
647	        : "Measurement starts once the account is live.";
648	  }
649	
650	  return {
651	    usedMB: a.diskUsedMB,
652	    quotaMB: a.diskQuotaMB,
653	    inodes: a.inodesUsed,
654	    measuredAt: a.usageAt?.toISOString() ?? null,
655	    parts,
656	    backupCount: backups.length,
657	    backupBytes: backups.reduce((s, b) => s + b.sizeBytes, 0),
658	    note,
659	  };
660	}
