663	
664	export type HostingActivityItem = {
665	  id: string;
666	  kind: string;
667	  label: string;
668	  detail: string | null;
669	  status: string;
670	  at: string;
671	};
672	
673	const TASK_LABELS: Record<string, string> = {
674	  PHP_SWITCH: "PHP version changed",
675	  WORDPRESS_INSTALL: "WordPress installed",
676	  APP_INSTALL: "App installed",
677	  BACKUP: "Backup created",
678	  RESTORE: "Backup restored",
679	  SUSPEND: "Account suspended",
680	  UNSUSPEND: "Account resumed",
681	  TERMINATE: "Account terminated",
682	  CREATE_SUBDOMAIN: "Subdomain created",
683	  DELETE_SUBDOMAIN: "Subdomain removed",
684	  CREATE_ADDON_DOMAIN: "Domain added",
685	  DELETE_ADDON_DOMAIN: "Domain removed",
686	  CREATE_CRON: "Cron job added",
687	  DELETE_CRON: "Cron job removed",
688	  INSTALL_DBTOOL: "Database tool installed",
689	  ENSURE_DBMGR: "Database access prepared",
690	  APPLY_PLAN_LIMITS: "Plan limits applied",
691	  RESET_DB_PASSWORD: "Database password reset",
692	  SET_PRIMARY_DOMAIN: "Primary domain changed",
693	  CREATE_FTP_USER: "SFTP login created",
694	  DELETE_FTP_USER: "SFTP login removed",
695	  RESET_FTP_PASSWORD: "SFTP password reset",
696	  CAPTURE_SITE_THUMB: "Website preview captured",
697	};
698	
699	/**
700	 * What has actually happened to this hosting plan, newest first.
701	 *
702	 * Every row is a real HostingTask — the queue every panel operation already goes
703	 * through. There is no synthetic "welcome" entry and no entry for anything the
704	 * platform did not run.
705	 */
706	export async function listHostingActivity(accountId: string, limit = 12): Promise<HostingActivityItem[]> {
707	  const ctx = await ownedAccount(accountId);
708	  if ("error" in ctx) return [];
709	  const rows = await db.hostingTask.findMany({
710	    where: { accountId },
711	    orderBy: { createdAt: "desc" },
712	    take: Math.min(50, Math.max(1, limit)),
713	    select: { id: true, kind: true, status: true, error: true, result: true, createdAt: true, updatedAt: true },
714	  });
715	  return rows.map((t) => {
716	    let detail: string | null = t.error;
717	    if (!detail && t.result) {
718	      try {
719	        const r = JSON.parse(t.result) as { app?: string; note?: string };
720	        detail = r.note ?? (r.app ? String(r.app) : null);
721	      } catch { /* a non-JSON result is not a detail */ }
722	    }
723	    return {
724	      id: t.id,
725	      kind: t.kind,
726	      label: TASK_LABELS[t.kind] ?? t.kind.toLowerCase().replace(/_/g, " "),
727	      detail,
728	      status: t.status,
729	      at: (t.updatedAt ?? t.createdAt).toISOString(),
730	    };
731	  });
732	}
