1	import { db } from "@/lib/db";
2	
3	/* Availability, recorded and read.
4	 *
5	 * Proxmox cannot answer "what was this VM's uptime last month" — `vmStatus`
6	 * reports only the present, and the RRD series carries load, not up/down. So
7	 * the worker samples on a cadence (worker/uptime.ts) and this file owns both
8	 * ends of that: `recordSample` writes, `uptimePercent` reads.
9	 *
10	 * The one rule worth stating out loud: a day with no samples is NOT 0% uptime,
11	 * it is "not measured". Averaging unmeasured days in would report an outage
12	 * that never happened — which is worse than reporting nothing, because a
13	 * customer would act on it. Every read below skips days where total === 0. */
14	
15	export const UPTIME_WINDOW_DAYS = 30;
16	
17	/** UTC midnight for a timestamp — the key each day's counters live under. */
18	export function utcDay(at: Date = new Date()): Date {
19	  return new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
20	}
21	
22	/**
23	 * Fold one observation into today's counters. Called once per server per sweep.
24	 * Upsert rather than read-modify-write so two workers sampling concurrently
25	 * cannot lose an increment.
26	 */
27	export async function recordSample(serverId: string, up: boolean, at: Date = new Date()) {
28	  const date = utcDay(at);
29	  await db.serverUptimeDaily.upsert({
30	    where: { serverId_date: { serverId, date } },
31	    create: { serverId, date, up: up ? 1 : 0, total: 1 },
32	    update: { up: { increment: up ? 1 : 0 }, total: { increment: 1 } },
33	  });
34	}
35	
36	export type UptimeRead = {
37	  /** null when nothing was measured in the window — render "—", never "0%". */
38	  percent: number | null;
39	  /** How many samples the number rests on, so a caller can judge it. */
40	  samples: number;
41	  days: number;
42	};
43	
44	/**
45	 * Availability across every server passed, over the trailing window.
46	 *
47	 * Pooled, not a mean-of-means: a server measured for two days should not weigh
48	 * the same as one measured for thirty. Summing samples first gives the honest
49	 * figure — the share of all observations in which the estate was up.
50	 */
51	export async function uptimeFor(serverIds: string[], windowDays = UPTIME_WINDOW_DAYS): Promise<UptimeRead> {
52	  if (serverIds.length === 0) return { percent: null, samples: 0, days: 0 };
53	  const since = utcDay(new Date(Date.now() - windowDays * 86_400_000));
54	
55	  const rows = await db.serverUptimeDaily.findMany({
56	    where: { serverId: { in: serverIds }, date: { gte: since }, total: { gt: 0 } },
57	    select: { up: true, total: true, date: true },
58	  });
59	  if (rows.length === 0) return { percent: null, samples: 0, days: 0 };
60	
61	  const up = rows.reduce((n, r) => n + r.up, 0);
62	  const total = rows.reduce((n, r) => n + r.total, 0);
63	  const days = new Set(rows.map((r) => r.date.getTime())).size;
64	
65	  // Two decimals: the figure the design shows is "99.98%", and rounding to a
66	  // whole number would collapse every good month onto "100%".
67	  return { percent: Math.round((up / total) * 10_000) / 100, samples: total, days };
68	}
69	
70	/** "99.98%" / "—". Formatting lives here so every surface agrees. */
71	export function formatUptime(read: UptimeRead): string {
72	  return read.percent === null ? "—" : `${read.percent.toFixed(2)}%`;
73	}
